use vesper_grammar::der::*;
fn main() -> std::result::Result<(), Box<dyn std::error::Error>> {
    // Independently generated by OpenSSL3.5.7 asn1parse -genconf (test records
    // the exact config). This is generic DER, not algorithm/key validation.
    let expected = [
        0x30, 0x1c, 1, 1, 0xff, 2, 2, 0xff, 0x7f, 3, 2, 0, 0xa0, 4, 2, 0, 0xff, 5, 0, 6, 9, 0x2a,
        0x86, 0x48, 0x86, 0xf7, 0x0d, 1, 1, 1,
    ];
    let children = [
        Value::Boolean(true),
        Value::Integer(&[0xff, 0x7f]),
        Value::BitString {
            unused_bits: 0,
            bytes: &[0xa0],
        },
        Value::OctetString(&[0, 0xff]),
        Value::Null,
        Value::ObjectIdentifier(&[0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 1, 1, 1]),
    ];
    let mut out = [0xab; 64];
    let len = encode_into(
        &Value::Sequence(&children),
        &Schema::Any,
        &mut out,
        Limits::default(),
    )?;
    assert_eq!(&out[..len], expected);
    let doc = parse_exact(&out[..len], &Schema::Any, Limits::default())?;
    assert_eq!(doc.node_count(), 7);
    assert_eq!(doc.root().children().nth(1).unwrap().as_i64()?, -129);
    let set_values = [Value::Integer(&[2]), Value::Integer(&[1])];
    let schema = Schema::SetOf(&Schema::Integer);
    let mut set = [0xab; 16];
    let n = encode_into(
        &Value::SetOf(&set_values),
        &schema,
        &mut set,
        Limits::default(),
    )?;
    assert_eq!(&set[..n], &[0x31, 6, 2, 1, 1, 2, 1, 2]);
    assert!(parse_exact(&set[..n], &Schema::Any, Limits::default()).is_err());
    assert_eq!(
        parse_exact(&set[..n], &schema, Limits::default())?
            .root()
            .children()
            .count(),
        2
    );
    println!(
        "DER: OpenSSL fixture matched ({len} bytes, 7 nodes); typed SET OF sorted canonically ({n} bytes)"
    );
    Ok(())
}
